static const size_t EMBEDDED_DATA_JS_LEN = 35082;


static const char* get_mime_type(const char* path) {
    const char* dot = strrchr(path, '.');
    if (!dot) return "application/octet-stream";
    if (strcmp(dot, ".html") == 0) return "text/html; charset=utf-8";
    if (strcmp(dot, ".css") == 0) return "text/css; charset=utf-8";
    if (strcmp(dot, ".js") == 0) return "application/javascript; charset=utf-8";
    if (strcmp(dot, ".json") == 0) return "application/json";
    if (strcmp(dot, ".png") == 0) return "image/png";
    if (strcmp(dot, ".jpg") == 0 || strcmp(dot, ".jpeg") == 0) return "image/jpeg";
    if (strcmp(dot, ".svg") == 0) return "image/svg+xml";
    if (strcmp(dot, ".apk") == 0) return "application/vnd.android.package-archive";
    if (strcmp(dot, ".exe") == 0) return "application/vnd.microsoft.portable-executable";
    return "application/octet-stream";
}

void handle_client(SOCKET client) {
    char buffer[BUFFER_SIZE];
    int bytes_received = recv(client, buffer, sizeof(buffer) - 1, 0);
    if (bytes_received <= 0) {
        closesocket(client);
        return;
    }
    buffer[bytes_received] = '\0';

    char method[16], url[512], protocol[16];
    if (sscanf(buffer, "%15s %511s %15s", method, url, protocol) < 2) {
        closesocket(client);
        return;
    }

    if (strcmp(method, "GET") != 0 && strcmp(method, "HEAD") != 0) {
        const char* err = "HTTP/1.1 405 Method Not Allowed\r\nContent-Length: 0\r\nConnection: close\r\n\r\n";
        send(client, err, (int)strlen(err), 0);
        closesocket(client);
        return;
    }

    char* query = strchr(url, '?');
    if (query) *query = '\0';

    const char* file_path = url;
    if (strcmp(file_path, "/") == 0) {
        file_path = "/hospital.html";
    }

    const char* disk_rel = file_path;
    if (disk_rel[0] == '/') disk_rel++;

    FILE* f = fopen(disk_rel, "rb");
    if (f) {
        fseek(f, 0, SEEK_END);
        long fsize = ftell(f);
        fseek(f, 0, SEEK_SET);

        char header[512];
        const char* mime = get_mime_type(file_path);
        int hlen = sprintf(header, "HTTP/1.1 200 OK\r\nContent-Type: %s\r\nContent-Length: %ld\r\nAccess-Control-Allow-Origin: *\r\nConnection: close\r\n\r\n", mime, fsize);
        send(client, header, hlen, 0);

        char chunk[16384];
        size_t n;
        while ((n = fread(chunk, 1, sizeof(chunk), f)) > 0) {
            send(client, chunk, (int)n, 0);
        }
        fclose(f);
        closesocket(client);
        return;
    }

    if (strcmp(file_path, "/hospital.html") == 0) {
        char header[512];
        int hlen = sprintf(header, "HTTP/1.1 200 OK\r\nContent-Type: text/html; charset=utf-8\r\nContent-Length: %zu\r\nAccess-Control-Allow-Origin: *\r\nConnection: close\r\n\r\n", EMBEDDED_HOSPITAL_HTML_LEN);
        send(client, header, hlen, 0);
        send(client, (const char*)EMBEDDED_HOSPITAL_HTML, (int)EMBEDDED_HOSPITAL_HTML_LEN, 0);
        closesocket(client);
        return;
    }

    if (strcmp(file_path, "/js/data.js") == 0) {
        char header[512];
        int hlen = sprintf(header, "HTTP/1.1 200 OK\r\nContent-Type: application/javascript; charset=utf-8\r\nContent-Length: %zu\r\nAccess-Control-Allow-Origin: *\r\nConnection: close\r\n\r\n", EMBEDDED_DATA_JS_LEN);
        send(client, header, hlen, 0);
        send(client, (const char*)EMBEDDED_DATA_JS, (int)EMBEDDED_DATA_JS_LEN, 0);
        closesocket(client);
        return;
    }

    const char* not_found = "HTTP/1.1 404 Not Found\r\nContent-Type: text/plain\r\nContent-Length: 13\r\nConnection: close\r\n\r\n404 Not Found";
    send(client, not_found, (int)strlen(not_found), 0);
    closesocket(client);
}

int main() {
    WSADATA wsa;
    if (WSAStartup(MAKEWORD(2, 2), &wsa) != 0) {
        printf("[ERROR] Winsock initialization failed.\n");
        return 1;
    }

    SOCKET server = socket(AF_INET, SOCK_STREAM, 0);
    if (server == INVALID_SOCKET) {
        printf("[ERROR] Failed to create socket.\n");
        WSACleanup();
        return 1;
    }

    int opt = 1;
    setsockopt(server, SOL_SOCKET, SO_REUSEADDR, (const char*)&opt, sizeof(opt));

    struct sockaddr_in addr;
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = htonl(INADDR_LOOPBACK);
    addr.sin_port = htons(PORT);

    if (bind(server, (struct sockaddr*)&addr, sizeof(addr)) == SOCKET_ERROR) {
        printf("[WARNING] Port %d busy, trying port %d...\n", PORT, PORT + 1);
        addr.sin_port = htons(PORT + 1);
        if (bind(server, (struct sockaddr*)&addr, sizeof(addr)) == SOCKET_ERROR) {
            printf("[ERROR] Could not bind to port %d or %d.\n", PORT, PORT + 1);
            closesocket(server);
            WSACleanup();
            return 1;
        }
    }

    int current_port = ntohs(addr.sin_port);
    if (listen(server, 20) == SOCKET_ERROR) {
        printf("[ERROR] Listen failed.\n");
        closesocket(server);
        WSACleanup();
        return 1;
    }

    char app_url[256];
    sprintf(app_url, "http://127.0.0.1:%d/hospital.html", current_port);

    printf("=====================================================================\n");
    printf("     GREEN+ CORRIDOR - HOSPITAL CAD & DRIVER MANAGEMENT DESKTOP      \n");
    printf("=====================================================================\n");
    printf("  [STATUS] Active Local CAD Server Running\n");
    printf("  [URL]    %s\n", app_url);
    printf("  [PORT]   %d\n", current_port);
    printf("---------------------------------------------------------------------\n");
    printf("  * Hospital CAD Sign In & Fox Backend Authentication Active\n");
    printf("  * Ambulance Driver In-Cab Setup (Unique ID & Passwords) Active\n");
    printf("  * Live AIS-140 GPS Telemetry Link Synchronized\n");
    printf("---------------------------------------------------------------------\n");
    printf("  Launching Hospital Desktop CAD window...\n");
    printf("  (Keep this window open while using the application. Press Ctrl+C to exit)\n");
    printf("=====================================================================\n\n");

    char app_arg[300];
    sprintf(app_arg, "--app=%s", app_url);

    HINSTANCE hEdge = ShellExecuteA(NULL, "open", "msedge.exe", app_arg, NULL, SW_SHOWNORMAL);
    if ((INT_PTR)hEdge <= 32) {
        HINSTANCE hChrome = ShellExecuteA(NULL, "open", "chrome.exe", app_arg, NULL, SW_SHOWNORMAL);
        if ((INT_PTR)hChrome <= 32) {
            ShellExecuteA(NULL, "open", app_url, NULL, NULL, SW_SHOWNORMAL);
        }
    }

    while (1) {
        struct sockaddr_in client_addr;
        int client_len = sizeof(client_addr);
        SOCKET client = accept(server, (struct sockaddr*)&client_addr, &client_len);
        if (client != INVALID_SOCKET) {
            handle_client(client);
        }
    }

    closesocket(server);
    WSACleanup();
    return 0;
}
